package main

import (
	"os"
	"strings"
	"testing"
)

func pyTestConfig() *PythonConfig {
	return &PythonConfig{
		Types: map[string]PythonTypeConfig{"Item": {}, "Data": {}},
		Skip:  []string{"Output"},
	}
}

func TestRenderPythonGeneratesDataclasses(t *testing.T) {
	s := mustSchema(t, goTestSchema)
	file, err := RenderPython(s, pyTestConfig())
	if err != nil {
		t.Fatal(err)
	}
	if file.Name != "models_gen.py" {
		t.Fatalf("file name = %q", file.Name)
	}
	out := string(file.Content)
	for _, want := range []string{
		"# Code generated by tools/alyprotocol",
		"from __future__ import annotations",
		"from dataclasses import dataclass",
		"DATA_STATUS_BEGIN = \"BEGIN\"",
		"@dataclass",
		"class Data:",
		"status: str",
		"count: int",
		"optional_note: Optional[str] = None",
		"items: list[Item]",
		"def from_dict(cls, data: dict) -> \"Data\":",
		"[Item.from_dict(v) for v in (data.get(\"items\") or [])]",
	} {
		if !strings.Contains(out, want) {
			t.Errorf("missing %q in:\n%s", want, out)
		}
	}
	if strings.Index(out, "count: int") > strings.Index(out, "optional_note: Optional") {
		t.Errorf("required fields must come before optional fields in a dataclass:\n%s", out)
	}
	if strings.Contains(out, "class Output:") {
		t.Error("Output 应在 skip 中")
	}
}

func TestRenderPythonRequiresCoverage(t *testing.T) {
	s := mustSchema(t, goTestSchema)
	cfg := &PythonConfig{Types: map[string]PythonTypeConfig{}, Skip: []string{"Output"}}
	if _, err := RenderPython(s, cfg); err == nil {
		t.Fatal("expected coverage error")
	}
}

func TestRenderPythonRejectsOverlap(t *testing.T) {
	s := mustSchema(t, goTestSchema)
	cfg := pyTestConfig()
	cfg.Skip = append(cfg.Skip, "Data")
	if _, err := RenderPython(s, cfg); err == nil {
		t.Fatal("expected overlap error")
	}
}

func TestPyEnumConstSplitsCamelCase(t *testing.T) {
	if got := pyEnumConst("DownloadProgress", "status", "BEGIN"); got != "DOWNLOAD_PROGRESS_STATUS_BEGIN" {
		t.Fatalf("const = %q", got)
	}
	if got := pyEnumConst("CleanData", "mode", "keep"); got != "CLEAN_DATA_MODE_KEEP" {
		t.Fatalf("const = %q", got)
	}
}

func TestLoadPythonConfig(t *testing.T) {
	dir := t.TempDir()
	path := dir + "/python.json"
	bad := `{"types":{"Data":{}},"skip":["Output"],"extra":1}`
	if err := os.WriteFile(path, []byte(bad), 0o600); err != nil {
		t.Fatal(err)
	}
	if _, err := LoadPythonConfig(path); err == nil {
		t.Fatal("expected unknown-field error")
	}
	good := `{"types":{"Data":{}},"skip":["Output"]}`
	if err := os.WriteFile(path, []byte(good), 0o600); err != nil {
		t.Fatal(err)
	}
	cfg, err := LoadPythonConfig(path)
	if err != nil {
		t.Fatal(err)
	}
	if cfg.Types["Data"].Name != "Data" {
		t.Fatalf("default name = %q", cfg.Types["Data"].Name)
	}
}
